WITH joined AS (SELECT b.mktcode,b.tgtcode,b.bizdate,t.ma20,t.ma60 FROM `newzl`.`hsj_stock_hq_basic` b LEFT JOIN `newzl`.`hsj_stock_hq_basic_technical` t ON t.mktcode=b.mktcode AND t.tgtcode=b.tgtcode AND t.bizdate=b.bizdate), event_rows AS (SELECT mktcode,tgtcode,bizdate,(ma20>ma60 AND LAG(ma20) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate)<=LAG(ma60) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate)) OR (ma20<ma60 AND LAG(ma20) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate)>=LAG(ma60) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate)) AS occurred FROM joined), event_keys AS (SELECT DISTINCT mktcode,tgtcode FROM event_rows WHERE bizdate IN (SELECT bizdate FROM `newzl`.`hsj_stock_hq_basic` GROUP BY bizdate ORDER BY bizdate DESC LIMIT 5) AND occurred=TRUE), metrics AS (SELECT mktcode,tgtcode,(MAX_BY(ma20,bizdate)-MIN_BY(ma20,bizdate))*100/NULLIF(ABS(MIN_BY(ma20,bizdate)),0) AS growth20,(MAX_BY(ma60,bizdate)-MIN_BY(ma60,bizdate))*100/NULLIF(ABS(MIN_BY(ma60,bizdate)),0) AS growth60 FROM joined WHERE bizdate IN (SELECT bizdate FROM `newzl`.`hsj_stock_hq_basic` GROUP BY bizdate ORDER BY bizdate DESC LIMIT 5) GROUP BY mktcode,tgtcode) SELECT b.mktcode,b.tgtcode,b.bizdate FROM `newzl`.`hsj_stock_hq_basic` b JOIN event_keys e ON e.mktcode=b.mktcode AND e.tgtcode=b.tgtcode JOIN metrics m ON m.mktcode=b.mktcode AND m.tgtcode=b.tgtcode WHERE b.bizdate='2026-04-14' AND m.growth20>-1000 AND m.growth60>-1000;
